using System;
using System.Collections.Generic;
using System.IO;
using Game.Core;
using Game.Core.Localization;
using Game.Save;
using Game.UI;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.UI;

namespace Game.EditorTools
{
    /// <summary>
    /// Rebuilds the game's menus from code (STANDALONE_RELEASE_ROADMAP.md TASK 054).
    ///
    /// **This is the replacement KNOWN_ISSUES.md asked for.** Its TASK 008 entry records
    /// that <c>MainMenu.unity</c>'s whole hierarchy and the pause panel were generated by a
    /// one-off editor script that was not kept, and concludes that a real UI pass "replaces
    /// this wholesale rather than editing it in place". The difference between that script
    /// and this one is that this one is checked in, re-runnable and idempotent: running it
    /// twice produces the same scene, so the menu's layout is a thing in version control
    /// that can be reviewed in a diff, rather than a thing in a scene file that can only be
    /// edited by dragging.
    ///
    /// It deletes the panels it owns and builds them again, which means **it is the layout**
    /// — a widget moved by hand in the Inspector will be gone the next time this runs. That
    /// is the intended trade: a hand-nudged position is exactly what put the word PAUSED on
    /// top of the Resume button and a slider's fill across the difficulty row.
    ///
    /// Wiring is done here too, through <see cref="SerializedObject"/>. A rebuild that left
    /// <see cref="MainMenuController"/>'s references dangling would produce a menu that
    /// looks right and does nothing, which is worse than the layout it replaced.
    /// </summary>
    public static class UiAuthoring
    {
        private const string MainMenuScene = "Assets/Scenes/MainMenu.unity";

        private static readonly string[] GameplayScenes =
        {
            "Assets/Scenes/Avarsha.unity",
            "Assets/Scenes/Agniya.unity"
        };

        /// <summary>Panels this tool owns. Anything else under the canvas is left alone.</summary>
        private static readonly string[] OwnedMainMenuPanels =
        {
            "Background", "RootPanel", "NewGamePanel", "LoadPanel",
            "SettingsPanel", "ControlsPanel", "HelpPanel", "CreditsPanel"
        };

        [MenuItem("Game/UI/Rebuild all menus")]
        public static void RebuildAllMenuItem() => Debug.Log(RebuildAll());

        /// <summary>
        /// Queues a rebuild on the next editor tick and writes the outcome to
        /// <paramref name="logPath"/>. The command pipeline allows five seconds on the main
        /// thread and opening and saving three scenes costs more than that.
        /// </summary>
        public static string RebuildDeferred(string logPath)
        {
            if (File.Exists(logPath))
            {
                File.Delete(logPath);
            }

            EditorApplication.CallbackFunction run = null;
            run = () =>
            {
                EditorApplication.update -= run;

                string result;
                try
                {
                    result = RebuildAll();
                }
                catch (Exception error)
                {
                    result = "FAILED: " + error;
                }

                File.WriteAllText(logPath, result);
            };

            EditorApplication.update += run;
            return "queued; poll " + logPath;
        }

        public static string RebuildAll()
        {
            var log = new List<string>();
            var originalScene = EditorSceneManager.GetActiveScene().path;

            RebuildMainMenu(log);
            foreach (var scene in GameplayScenes)
            {
                RebuildGameplayMenu(scene, log);
            }

            if (!string.IsNullOrEmpty(originalScene))
            {
                EditorSceneManager.OpenScene(originalScene, OpenSceneMode.Single);
            }

            return string.Join("\n", log);
        }

        // ------------------------------------------------------------------- main menu

        private static void RebuildMainMenu(List<string> log)
        {
            var scene = EditorSceneManager.OpenScene(MainMenuScene, OpenSceneMode.Single);
            var controller = Find<MainMenuController>();
            if (controller == null)
            {
                log.Add("FAILED: no MainMenuController in " + MainMenuScene);
                return;
            }

            var canvas = FindCanvas();
            if (canvas == null)
            {
                log.Add("FAILED: no Canvas in " + MainMenuScene);
                return;
            }

            // The Main Menu is where the text-size slider has lived since TASK 017, and
            // its canvas was the one canvas in the game with nothing to apply it — the two
            // gameplay canvases had the component and the setting they were given did
            // nothing, so the feature was broken at both ends and looked present at both.
            if (canvas.GetComponent<Game.UI.UIScaleApplier>() == null)
            {
                canvas.gameObject.AddComponent<Game.UI.UIScaleApplier>();
                log.Add("     " + MainMenuScene + ": added the missing UIScaleApplier");
            }

            var removed = ClearOwnedPanels(canvas.transform, OwnedMainMenuPanels);

            // A background of its own, rather than relying on the camera's clear colour.
            // The menu rendered as whatever colour the camera happened to be set to, which
            // is a dependency nobody would expect and nothing records.
            var background = UiBuilder.FullScreen(canvas.transform, "Background");
            background.gameObject.AddComponent<Image>().color = new Color(0.07f, 0.05f, 0.08f, 1f);
            background.SetAsFirstSibling();

            var root = BuildMainRoot(canvas.transform, out var buttons);
            var newGame = BuildNewGamePanel(canvas.transform, out var difficultyButtons, out var newGameBack);
            var load = BuildLoadPanel(canvas.transform, out var slotRows, out var loadBack);
            var settings = BuildSettingsPanel(canvas.transform, out var settingsComponent);
            var controls = BuildControlsPanel(canvas.transform, out var remap, out var controlsBack);
            var help = BuildHelpPanel(canvas.transform, out var helpComponent);
            var credits = BuildCreditsPanel(canvas.transform, out var creditsBack);

            var serialized = new SerializedObject(controller);
            Set(serialized, "rootPanel", root.gameObject);
            Set(serialized, "newGamePanel", newGame.gameObject);
            Set(serialized, "loadPanel", load.gameObject);
            Set(serialized, "settingsPanel", settings.gameObject);
            Set(serialized, "controlsPanel", controls.gameObject);
            Set(serialized, "helpPanel", help.gameObject);
            Set(serialized, "creditsPanel", credits.gameObject);

            Set(serialized, "newGameButton", buttons["new_game"]);
            Set(serialized, "continueButton", buttons["continue"]);
            Set(serialized, "loadButton", buttons["load"]);
            Set(serialized, "settingsButton", buttons["settings"]);
            Set(serialized, "controlsButton", buttons["controls"]);
            Set(serialized, "helpButton", buttons["help"]);
            Set(serialized, "creditsButton", buttons["credits"]);
            Set(serialized, "quitButton", buttons["quit"]);

            SetArray(serialized, "difficultyButtons", difficultyButtons);
            Set(serialized, "newGameBackButton", newGameBack);
            Set(serialized, "loadBackButton", loadBack);
            Set(serialized, "controlsBackButton", controlsBack);
            Set(serialized, "creditsBackButton", creditsBack);

            Set(serialized, "settings", settingsComponent);
            Set(serialized, "remapUI", remap);
            Set(serialized, "help", helpComponent);

            var rows = serialized.FindProperty("slotRows");
            rows.arraySize = slotRows.Count;
            for (var i = 0; i < slotRows.Count; i++)
            {
                var element = rows.GetArrayElementAtIndex(i);
                element.FindPropertyRelative("Slot").enumValueIndex = (int)slotRows[i].Slot;
                element.FindPropertyRelative("Label").objectReferenceValue = slotRows[i].Label;
                element.FindPropertyRelative("LoadRowButton").objectReferenceValue = slotRows[i].Button;
            }

            serialized.ApplyModifiedPropertiesWithoutUndo();

            // Only the root is on when the scene loads; the rest are opened by the menu.
            foreach (var panel in new[] { newGame, load, settings, controls, help, credits })
            {
                panel.gameObject.SetActive(false);
            }

            root.gameObject.SetActive(true);

            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            log.Add($"OK   {MainMenuScene}: replaced {removed} panel(s), built 7 screens");
        }

        private static RectTransform BuildMainRoot(Transform canvas, out Dictionary<string, Button> buttons)
        {
            var root = UiBuilder.FullScreen(canvas, "RootPanel");
            var panel = UiBuilder.Panel(root, "RootContent", 900f, background: false);

            UiBuilder.Label(panel, StringKeys.MenuLabelTitle, UiTheme.TextRole.Title);
            UiBuilder.Spacer(panel, UiTheme.Spacing * 3f);

            buttons = new Dictionary<string, Button>
            {
                ["new_game"] = UiBuilder.Button(panel, StringKeys.MenuLabelNewGame, confirm: true),
                ["continue"] = UiBuilder.Button(panel, StringKeys.MenuLabelContinue),
                ["load"] = UiBuilder.Button(panel, StringKeys.MenuLabelLoad),
                ["settings"] = UiBuilder.Button(panel, StringKeys.MenuLabelSettings),
                ["controls"] = UiBuilder.Button(panel, StringKeys.MenuLabelControls),
                ["help"] = UiBuilder.Button(panel, StringKeys.MenuLabelHelp),
                ["credits"] = UiBuilder.Button(panel, StringKeys.MenuLabelCredits),
                ["quit"] = UiBuilder.Button(panel, StringKeys.MenuLabelQuit)
            };

            // The version, in the corner, where a tester looks for it when reporting a
            // bug. OWNER_RELEASE_CHECKLIST.md asks testers for the build they played and
            // until now the only place that said so was a text file in the ZIP.
            var footer = UiBuilder.FullScreen(root, "Footer");
            var version = UiBuilder.Label(footer, null, UiTheme.TextRole.Small, TextAnchor.LowerRight);
            // Written by a component at runtime, not baked in here. Text saved into a
            // scene belongs to no key and no language, which is the gap this task closed.
            // Applied once here as well as at runtime, so the Editor and the capture tool
            // show the real line rather than an empty corner — the same reason the builder
            // lets LocalizedLabel write its English through at build time.
            version.gameObject.AddComponent<VersionLabel>().Apply();
            UiBuilder.Stretch(version.rectTransform);
            version.rectTransform.offsetMin = new Vector2(0f, UiTheme.PanelPadding);
            version.rectTransform.offsetMax = new Vector2(-UiTheme.PanelPadding, 0f);

            return root;
        }

        private static RectTransform BuildNewGamePanel(Transform canvas, out List<Button> difficulties,
            out Button back)
        {
            var root = UiBuilder.FullScreen(canvas, "NewGamePanel");
            var panel = UiBuilder.Panel(root, "NewGameContent", 640f);

            UiBuilder.Label(panel, StringKeys.MenuLabelNewGameTitle, UiTheme.TextRole.Title);
            UiBuilder.Spacer(panel, UiTheme.Spacing);

            difficulties = new List<Button>();
            foreach (DifficultyMode mode in Enum.GetValues(typeof(DifficultyMode)))
            {
                var key = StringKeys.MenuDifficultyPrefix + mode.ToString().ToLowerInvariant();
                difficulties.Add(UiBuilder.Button(panel, key, confirm: mode == DifficultyMode.Normal, width: 560f));

                // The one line that tells a first-time player what they are choosing.
                // Four unexplained words — Story, Normal, Warrior, Mythic — is a guess,
                // and the guess that goes wrong is the one that makes someone quit.
                var description = UiBuilder.Paragraph(panel, key + ".description", UiTheme.TextRole.Muted);
                description.alignment = TextAnchor.UpperCenter;
                UiBuilder.Spacer(panel, UiTheme.Spacing);
            }

            back = UiBuilder.Button(panel, StringKeys.MenuLabelBack);
            return root;
        }

        private readonly struct SlotRowBuild
        {
            public readonly SaveSlot Slot;
            public readonly Text Label;
            public readonly Button Button;

            public SlotRowBuild(SaveSlot slot, Text label, Button button)
            {
                Slot = slot;
                Label = label;
                Button = button;
            }
        }

        private static RectTransform BuildLoadPanel(Transform canvas, out List<SlotRowBuild> rows, out Button back)
        {
            var root = UiBuilder.FullScreen(canvas, "LoadPanel");
            var panel = UiBuilder.Panel(root, "LoadContent", 720f);

            UiBuilder.Label(panel, StringKeys.MenuLabelLoadTitle, UiTheme.TextRole.Title);
            UiBuilder.Spacer(panel, UiTheme.Spacing);

            rows = new List<SlotRowBuild>();
            foreach (SaveSlot slot in Enum.GetValues(typeof(SaveSlot)))
            {
                var button = UiBuilder.Button(panel, null, width: 640f);
                button.name = "Slot_" + slot;

                // The row's text is written by MainMenuController from the file on disk,
                // so it has no key of its own: the slot's name, its scene and its
                // timestamp are data, not words to translate.
                var label = button.GetComponentInChildren<Text>(true);
                label.alignment = TextAnchor.MiddleLeft;
                label.rectTransform.offsetMin = new Vector2(UiTheme.Spacing * 2f, 0f);
                label.rectTransform.offsetMax = new Vector2(-UiTheme.Spacing * 2f, 0f);
                rows.Add(new SlotRowBuild(slot, label, button));
            }

            UiBuilder.Spacer(panel, UiTheme.Spacing);
            back = UiBuilder.Button(panel, StringKeys.MenuLabelBack);
            return root;
        }

        private static RectTransform BuildSettingsPanel(Transform canvas, out SettingsPanel component)
        {
            var root = UiBuilder.FullScreen(canvas, "SettingsPanel");
            component = root.gameObject.AddComponent<SettingsPanel>();
            component.Configure(root, background: true, display: true);
            return root;
        }

        private static RectTransform BuildControlsPanel(Transform canvas, out RemapUI remap, out Button back)
        {
            var root = UiBuilder.FullScreen(canvas, "ControlsPanel");
            var panel = UiBuilder.Panel(root, "ControlsContent", 820f);

            UiBuilder.Label(panel, StringKeys.MenuLabelControlsTitle, UiTheme.TextRole.Title);
            var content = UiBuilder.Scroll(panel, "RemapScroll", 420f);

            var reset = UiBuilder.Button(panel, StringKeys.MenuLabelResetBindings);
            back = UiBuilder.Button(panel, StringKeys.MenuLabelBack);

            remap = root.gameObject.AddComponent<RemapUI>();
            remap.Configure(InputActions(), content);

            // A persistent listener, not AddListener: a runtime listener added at edit
            // time is not serialized, so the saved scene would contain a Reset button
            // wired to nothing — which looks identical in the Inspector.
            UnityEditor.Events.UnityEventTools.AddPersistentListener(reset.onClick, remap.ResetToDefaults);
            return root;
        }

        private static RectTransform BuildHelpPanel(Transform canvas, out HelpPanel component)
        {
            var root = UiBuilder.FullScreen(canvas, "HelpPanel");
            component = root.gameObject.AddComponent<HelpPanel>();
            component.Configure(InputActions(), root);
            return root;
        }

        private static RectTransform BuildCreditsPanel(Transform canvas, out Button back)
        {
            var root = UiBuilder.FullScreen(canvas, "CreditsPanel");
            var panel = UiBuilder.Panel(root, "CreditsContent", 720f);

            UiBuilder.Label(panel, StringKeys.MenuLabelCreditsTitle, UiTheme.TextRole.Title);
            UiBuilder.Spacer(panel, UiTheme.Spacing);

            var title = UiBuilder.Paragraph(panel, StringKeys.MenuLabelTitle, UiTheme.TextRole.Heading);
            title.alignment = TextAnchor.UpperCenter;

            foreach (var key in new[]
                     {
                         StringKeys.CreditsMade, StringKeys.CreditsEngine,
                         StringKeys.CreditsAssets, StringKeys.CreditsThanks
                     })
            {
                var line = UiBuilder.Paragraph(panel, key, UiTheme.TextRole.Body);
                line.alignment = TextAnchor.UpperCenter;
                UiBuilder.Spacer(panel, UiTheme.Spacing);
            }

            back = UiBuilder.Button(panel, StringKeys.MenuLabelBack);
            return root;
        }

        // ------------------------------------------------------------- gameplay scenes

        private static void RebuildGameplayMenu(string scenePath, List<string> log)
        {
            var scene = EditorSceneManager.OpenScene(scenePath, OpenSceneMode.Single);
            var pause = Find<PauseMenu>();
            if (pause == null)
            {
                log.Add("FAILED: no PauseMenu in " + scenePath);
                return;
            }

            var serializedPause = new SerializedObject(pause);
            var panelProperty = serializedPause.FindProperty("pausePanel");
            var panel = panelProperty.objectReferenceValue as GameObject;

            if (panel == null)
            {
                log.Add("FAILED: PauseMenu in " + scenePath + " has no pausePanel");
                return;
            }

            var removed = 0;
            for (var i = panel.transform.childCount - 1; i >= 0; i--)
            {
                UnityEngine.Object.DestroyImmediate(panel.transform.GetChild(i).gameObject);
                removed++;
            }

            foreach (var stale in panel.GetComponents<GameMenu>())
            {
                UnityEngine.Object.DestroyImmediate(stale);
            }

            // The panel is the menu's canvas-sized root, so it has to fill the screen for
            // the scrim to cover anything.
            UiBuilder.Stretch((RectTransform)panel.transform);

            var menu = panel.AddComponent<GameMenu>();
            menu.Configure(pause, InputActions());

            WireHud(panel.transform.parent, log, scenePath);

            // PauseMenu used to hand controller focus to a Resume button it owned. GameMenu
            // builds its own and focuses it when the panel opens, so the old reference is
            // cleared rather than left pointing at a destroyed object.
            serializedPause.FindProperty("resumeButton").objectReferenceValue = null;
            serializedPause.ApplyModifiedPropertiesWithoutUndo();

            EditorSceneManager.MarkSceneDirty(scene);
            EditorSceneManager.SaveScene(scene);
            log.Add($"OK   {scenePath}: pause menu rebuilt, {removed} old child object(s) removed");
        }

        /// <summary>
        /// Gives <see cref="HudUI"/> the input asset the ToggleHud action lives on, and a
        /// label to say how to get the HUD back.
        ///
        /// The label has to sit outside the HUD root. It is shown at the moment the HUD is
        /// switched off, and anything parented under the thing being switched off would be
        /// switched off with it — which is the kind of mistake that is obvious once stated
        /// and invisible in a hierarchy.
        /// </summary>
        private static void WireHud(Transform canvas, List<string> log, string scenePath)
        {
            var hud = Find<HudUI>();
            if (hud == null || canvas == null)
            {
                log.Add("WARN " + scenePath + ": no HudUI to wire the HUD toggle into");
                return;
            }

            var existing = canvas.Find("HudHiddenHint");
            if (existing != null)
            {
                UnityEngine.Object.DestroyImmediate(existing.gameObject);
            }

            var hint = UiBuilder.FullScreen(canvas, "HudHiddenHint");
            var label = UiBuilder.Label(hint, null, UiTheme.TextRole.Body, TextAnchor.UpperCenter);
            UiBuilder.Stretch(label.rectTransform);
            label.rectTransform.offsetMin = new Vector2(0f, 0f);
            label.rectTransform.offsetMax = new Vector2(0f, -UiTheme.PanelPadding);
            label.color = UiTheme.Caution;
            hint.gameObject.SetActive(false);

            var serialized = new SerializedObject(hud);
            serialized.FindProperty("inputActions").objectReferenceValue = InputActions();
            serialized.FindProperty("hiddenHint").objectReferenceValue = label;
            serialized.ApplyModifiedPropertiesWithoutUndo();

            log.Add("     " + scenePath + ": HUD toggle wired (ToggleHud + return hint)");
        }

        // ------------------------------------------------------------------- utilities

        private static int ClearOwnedPanels(Transform canvas, string[] names)
        {
            var removed = 0;
            for (var i = canvas.childCount - 1; i >= 0; i--)
            {
                var child = canvas.GetChild(i);
                if (Array.IndexOf(names, child.name) < 0)
                {
                    continue;
                }

                UnityEngine.Object.DestroyImmediate(child.gameObject);
                removed++;
            }

            return removed;
        }

        private static InputActionAsset InputActions() =>
            AssetDatabase.LoadAssetAtPath<InputActionAsset>("Assets/Input/PlayerControls.inputactions");

        private static T Find<T>() where T : Component
        {
            foreach (var found in Resources.FindObjectsOfTypeAll<T>())
            {
                if (found.gameObject.scene.IsValid())
                {
                    return found;
                }
            }

            return null;
        }

        private static Canvas FindCanvas()
        {
            Canvas best = null;
            foreach (var canvas in Resources.FindObjectsOfTypeAll<Canvas>())
            {
                if (!canvas.gameObject.scene.IsValid() || canvas.transform.parent != null)
                {
                    continue;
                }

                if (best == null || canvas.transform.childCount > best.transform.childCount)
                {
                    best = canvas;
                }
            }

            return best;
        }

        private static void Set(SerializedObject target, string field, UnityEngine.Object value)
        {
            var property = target.FindProperty(field);
            if (property == null)
            {
                throw new InvalidOperationException($"{target.targetObject.GetType().Name} has no field '{field}'");
            }

            property.objectReferenceValue = value;
        }

        private static void SetArray(SerializedObject target, string field, List<Button> values)
        {
            var property = target.FindProperty(field);
            property.arraySize = values.Count;
            for (var i = 0; i < values.Count; i++)
            {
                property.GetArrayElementAtIndex(i).objectReferenceValue = values[i];
            }
        }
    }
}
